insert into public.retail_roles (id, name, category, markup_pct, require_terms, terms, description, is_system, active, menu_permissions) values
  ('sales_regional_partner', 'Regional Partner', 'sales_partner', 10.0, true, 'By registering as an ARGUS CNC Regional Partner, you agree to uphold our brand pricing guidelines, maintain active territory coverage, and adhere to our confidentiality and customer service standards. All orders are subject to regional quota allocations.', 'Authorized regional distribution partner with territory rights and 10% markup tier.', true, true, '["store_home", "store_listing", "store_cart", "store_quotes", "store_orders", "store_profile", "cat_cnc_machines", "cat_cutting_tools", "cat_spares", "cat_workholding", "cat_electrical", "cat_raw_materials", "cat_consumables", "cat_measuring", "cat_safety"]'::jsonb),
  ('sales_channel_partner', 'Channel Partner', 'sales_partner', 15.0, true, 'By registering as an ARGUS CNC Channel Partner, you agree to our resale terms, minimum advertised price (MAP) policies, and prompt payment settlements. Commercial warranty and return terms apply.', 'Certified industrial channel sales partner with 15% markup tier.', true, true, '["store_home", "store_listing", "store_cart", "store_quotes", "store_orders", "store_profile", "cat_cnc_machines", "cat_cutting_tools", "cat_spares", "cat_workholding", "cat_electrical", "cat_raw_materials", "cat_consumables", "cat_measuring", "cat_safety"]'::jsonb),
  ('sales_referral_partner', 'Referral Partner', 'sales_partner', 5.0, true, 'By registering as an ARGUS CNC Referral Partner, you agree that referrals must be bona fide commercial inquiries. Commission entitlements are calculated on the 5% tier basis upon order delivery.', 'Registered commercial referral agent with 5% markup tier.', true, true, '["store_home", "store_listing", "store_cart", "store_quotes", "store_orders", "store_profile", "cat_cnc_machines", "cat_cutting_tools", "cat_spares", "cat_workholding", "cat_electrical", "cat_raw_materials", "cat_consumables", "cat_measuring", "cat_safety"]'::jsonb),
  ('sales_user', 'Direct Sales User', 'sales_partner', 0.0, true, 'Standard direct sales representative agreement: confidential catalog pricing, customer order processing, and quotation terms apply.', 'Standard sales representative with base retail catalog pricing (0% markup).', true, true, '["store_home", "store_listing", "store_cart", "store_quotes", "store_orders", "store_profile", "cat_cnc_machines", "cat_cutting_tools", "cat_spares", "cat_workholding", "cat_electrical", "cat_raw_materials", "cat_consumables", "cat_measuring", "cat_safety"]'::jsonb),
  ('company_admin', 'Company Admin', 'internal', 0.0, false, '', 'Full company administration: manages catalog, inventory, users, and orders.', true, true, '["admin_dashboard", "admin_products", "admin_media", "admin_categories", "admin_users", "admin_settings", "admin_orders", "admin_quotes", "content_writer", "finance_review", "store_home", "store_listing", "store_cart", "store_quotes", "store_orders", "store_profile", "cat_cnc_machines", "cat_cutting_tools", "cat_spares", "cat_workholding", "cat_electrical", "cat_raw_materials", "cat_consumables", "cat_measuring", "cat_safety", "admin_invoice_profile"]'::jsonb),
